WITH valid AS (SELECT *, CONCAT(country, '/', device) AS country_device, COALESCE(browser, 'NONE') AS browser_clean FROM sessions WHERE country IS NOT NULL AND country IS DISTINCT FROM 'TH'), gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM valid), sessions_sessions AS (SELECT id, customer_id, browser, started_at, country, country_device, browser_clean, SUM(session_start_flag) OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, PERCENTILE_APPROX(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles, ROUND(SUM(session_no) / NULLIF(COUNT(CASE WHEN browser = 'Edge' THEN 1 END), 0), 2) AS session_no_per_edge, SUM(session_no) AS total_session_no FROM sessions_sessions GROUP BY DATE_TRUNC('YEAR', started_at);
